remediationSample:
Avoid redirecting to URLs built from user input.
If this is not possible, validate the arguments using a dedicated method and declare this method as a sanitization method for the quality rule. Example of such methods:

// ----------------------------------------------------------------------------
// 1) Java sample

import jakarta.servlet.http.HttpServletResponse;
import org.springframework.web.bind.annotation.*;

import java.io.IOException;
import java.net.*;

@RestController
public class RedirectControllerSecure {

  private static final String[] TRUSTED_HOSTS = {"www.castsoftware.com", "learn.microsoft.com"};

  @GetMapping("/go")
  public void go(@RequestParam String userInput, HttpServletResponse response) throws IOException {
    String safeUrl = trySanitizeRedirectUrl(userInput);
    if (safeUrl == null) { response.sendError(HttpServletResponse.SC_BAD_REQUEST, "The requested redirect target is not allowed."); return; }

    response.sendRedirect(safeUrl); // ✓ OK: redirection restricted to an allow-listed target
  }

  private static String trySanitizeRedirectUrl(String input) {
    if (input == null) return null;

    URI targetUri;
    try { targetUri = new URI(input); } catch (URISyntaxException e) { return null; }

    if (!targetUri.isAbsolute() || !("http".equalsIgnoreCase(targetUri.getScheme()) || "https".equalsIgnoreCase(targetUri.getScheme()))) return null;

    for (String trustedHost : TRUSTED_HOSTS)
      if (trustedHost.equalsIgnoreCase(targetUri.getHost()))
        return targetUri.toString();

    return null;
  }
}


// ----------------------------------------------------------------------------
// 2) C# sample

using Confluent.Kafka;
using Microsoft.AspNetCore.Mvc;
using System;
using System.Collections.Generic;

internal class Program : ControllerBase
{
  private static Dictionary config;
  private static readonly string[] TrustedHosts = { "www.castsoftware.com", "learn.microsoft.com" };

  private void ProcessRedirectFromKafka_secure()
  {
    using var consumer = new ConsumerBuilder(config).Build();
    consumer.Subscribe("redirect-topic");
    var result = consumer.Consume(TimeSpan.FromSeconds(10));

    if (result is null) return;

    string userInput = result.Message.Value;

    Uri? safeUri = TrySanitizeRedirectUrl(userInput);
    if (safeUri == null) return;

    Redirect(safeUri.ToString()); // ✓ OK: redirection restricted to an allow-listed target
  }

  private static Uri? TrySanitizeRedirectUrl(string? input)
  {
    if (input == null) return null;

    Uri targetUri;
    try { targetUri = new Uri(input, UriKind.Absolute); } catch (UriFormatException) { return null; }

    if (targetUri.Scheme != Uri.UriSchemeHttp && targetUri.Scheme != Uri.UriSchemeHttps) return null;

    foreach (string trustedHost in TrustedHosts)
      if (string.Equals(targetUri.Host, trustedHost, StringComparison.OrdinalIgnoreCase))
        return targetUri;

    return null;
  }
}

